INSERT INTO public.subtag_ext (id, description, comments, added_on) VALUES ('t', 'Specifying Transformed Content', 'Subtags for the identification of content that has been transformed, including but not limited to: transliteration, transcription, and translation.', '2011-12-16');
INSERT INTO public.subtag_ext (id, description, comments, added_on) VALUES ('u', 'Unicode Locale', 'Subtags for the identification of language and cultural variations. Used to set behavior in locale APIs. Data is located in the "common/bcp47" directory inside the referenced URL. Unicode Technical Standard #35 (LDML) provides additional reference material defining the keys and values. For more details please see <http://cldr.unicode.org/index/bcp47-extension>.', '2010-09-02');
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'nu', 'Numbering system type key', false, NULL, 'numbers', NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'i0', 'Input Method Engine transform:   Used to indicate an input method transformation, such as one used by   a client-side input method. The first subfield in a sequence would   typically be a ''platform'' or vendor designation.', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'd0', 'Transform destination for non-languages/scripts.', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 's0', 'Transform source for non-languages/scripts.', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'm0', 'Transform extension mechanism:    to reference an authority or rules for a type of transformation', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'em', 'Emoji presentation style request', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'rg', 'Alternate region for determining certain data values (e.g. default currency and units) specified by rgScope', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'sd', 'Region subdivision', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'va', 'Common locale variant type key', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 't0', 'Machine Translation:          Used to indicate content that has been machine translated, or a request for a particular type of machine translation of content.         The first subfield in a sequence would typically be a ''platform'' or vendor designation.', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'dx', 'Scripts to exclude from dictionary break', false, NULL, NULL, 'multiple');
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'lb', 'Line break type key', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'lw', 'Line break key for CSS lev 3 word-break options', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'ss', 'Sentence break parameter key to control use of suppressions data', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'ca', 'Calendar algorithm key', false, NULL, 'calendar', 'incremental');
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'fw', 'First day of week', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'hc', 'Hour cycle (12 vs 24)', false, NULL, 'hours', NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'cf', 'Currency format key', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'cu', 'Currency type key', false, NULL, 'currency', NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'h0', 'Language mixed in to form hybrid language tag.    See http://unicode.org/reports/tr35/#Hybrid_Locale', false, NULL, NULL, 'single');
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('u', 'tz', 'Time zone key', false, NULL, 'timezone', NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'k0', 'Keyboard transform:    Used to indicate a keyboard transformation, such as one used by a client-side virtual keyboard.    The first subfield in a sequence would typically be a ''platform'' designation,    representing the platform that the keyboard is intended for.   The keyboard might or might not correspond to a keyboard mapping shipped by the vendor for the platform.   One or more subsequent fields may occur, but are only added where needed to distinguish from others.', false, NULL, NULL, NULL);
INSERT INTO public.subtag_ext_key (ext_id, id, description, deprecated, preferred, alias, value_type) VALUES ('t', 'x0', 'Private use transform type key.', false, NULL, NULL, 'any');
