INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'co', 'trad', 'Traditional style ordering (such as in Spanish)', false, NULL, 'collation');
INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'co', 'unihan', 'Pinyin ordering for Latin, Unihan radical-stroke ordering for CJK characters (used in Chinese)', false, NULL, 'collation');
INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'co', 'zhuyin', 'Pinyin ordering for Latin, zhuyin order for Bopomofo and CJK characters (used in Chinese)', false, NULL, 'collation');
INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'ka', 'noignore', 'Variable collation elements are not reset to ignorable', false, NULL, 'colAlternate');
