INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'kc', 'false', 'No special case level handling', false, NULL, 'colCaseLevel');
INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'kf', 'upper', 'Upper case to be sorted before lower case', false, NULL, 'colCaseFirst');
