INSERT INTO public.subtag_ext_key_type (ext_id, key_id, id, description, deprecated, preferred, alias) VALUES ('u', 'kn', 'true', 'A sequence of decimal digits is sorted at primary level with its numeric value', false, NULL, 'colNumeric');
